using System;using System.Web.Script.Serialization;
class HeroPassiveChecks{static void Check(bool v){if(!v)throw new Exception("passive check failed");}static void Main(){var b=new PartyCombatState();var a=new PartyUnit{id="aelia",name="艾莉娅",hp=1000,maxHp=1000,rank=1};var m=new PartyUnit{id="luchuan",name="陆川",hp=1000,maxHp=1000,attack=10,rank=2};var e=new PartyUnit{id="enemy",hp=1000,maxHp=1000,rank=1};b.heroes.Add(a);b.heroes.Add(m);b.enemies.Add(e);b.active="enemy";b.enemyDamage=2;b.defenseTargets.Add("aelia");b.phase="defense-question";PartyCombat.DefenseAnswer(b,true);Check(a.defenseSuccesses==1&&a.resolve==0);b.phase="defense-question";PartyCombat.DefenseAnswer(b,false);Check(a.defenseSuccesses==1);b.phase="defense-question";PartyCombat.DefenseAnswer(b,true);Check(a.resolve==1&&a.defenseSuccesses==0);b.phase="defense-question";PartyCombat.DefenseAnswer(b,true);var json=new JavaScriptSerializer();b=json.Deserialize<PartyCombatState>(json.Serialize(b));Check(b.heroes[0].defenseSuccesses==1);for(int i=0;i<2;i++){b.phase="attack-question";b.pendingHero="luchuan";b.pendingSkill="bolt";b.pendingTarget="enemy";PartyCombat.AttackAnswer(b,true);}Check(b.heroes[1].runeBoost==1&&b.heroes[1].attackSuccesses==0&&b.enemies[0].marks==0);Console.WriteLine("PASS two successes, wrong-answer retention, saved counter and independent curse stack");}}
